win.removeEventListener('hashchange',_render);win.addEventListener('hashchange',()=>render());

function setup(col,key,pn,isRev){
  const ids=[...(isRev?[]:$$('.chsec',col)),...$$('.ans',col)];
  $$('.chsec,.ans',col).forEach(s=>{
    const id=s.dataset.id,st=s.querySelector('.star'),dn=s.querySelector('.dn');
    if(st)st.setAttribute('aria-pressed',saved.has(id));
    if(dn)dn.setAttribute('aria-pressed',done.has(id));
    if(s.classList.contains('ans')){s.classList.toggle('rev',!!s.dataset.rev);$$('.rate button',s).forEach(b=>b.setAttribute('aria-pressed',rate[id]===b.dataset.r))}
  });
  $$('.p-hl',col).forEach(x=>x.classList.remove('p-hl'));
  $$('.ans-body>p,.ans-body li,.chsec>p,.chsec li,.co-b>p',col).forEach((x,i)=>{x.dataset.hk=key+pn+i;if(hl.has(x.dataset.hk))x.classList.add('p-hl')});
  root.classList.toggle('recall',recall&&pn==='pyq');
  const rc=$('#rc');if(rc)rc.onclick=()=>{recall=!recall;rc.setAttribute('aria-checked',recall);root.classList.toggle('recall',recall);$$('.ans',col).forEach(a=>{if(!recall){a.dataset.rev='';a.classList.remove('rev')}});save();toast(recall?'Answers hidden — try writing them first':'Answers visible')};
  const ex=$('#ex');if(ex)ex.onclick=()=>{const secs=$$('.chsec',col);if(!secs.length){return}const all=secs.every(s=>s.classList.contains('fold'));secs.forEach(s=>s.classList.toggle('fold',!all));ex.textContent=all?'Collapse all':'Expand all'};
  if(pn!=='pyq')root.classList.remove('recall');
}
doc.addEventListener('click',e=>{
  const chap=e.target.closest('.chap');
  if(chap&&!e.target.closest('.acts')){chap.closest('.chsec').classList.toggle('fold');return}
  const st=e.target.closest('.star');
  if(st){const s=st.closest('.chsec,.ans');const id=s.dataset.id;saved.has(id)?saved.delete(id):saved.add(id);st.setAttribute('aria-pressed',saved.has(id));save();toast(saved.has(id)?'Saved':'Removed from saved');return}
  const dn=e.target.closest('.dn');
  if(dn){const s=dn.closest('.chsec');const id=s.dataset.id;done.has(id)?done.delete(id):done.add(id);dn.setAttribute('aria-pressed',done.has(id));if(done.has(id)){s.classList.add('fold');toast('Chapter marked done')}save();renderNav(route);buildToc($('#col'),route.page,route.a==='pyq'?'pyq':'notes');return}
  const rv=e.target.closest('[data-act=reveal]');
  if(rv){const a=rv.closest('.ans');a.dataset.rev=1;a.classList.add('rev');return}
  const rt=e.target.closest('.rate button');
  if(rt){const a=rt.closest('.ans');rate[a.dataset.id]=rt.dataset.r;$$('.rate button',a).forEach(b=>b.setAttribute('aria-pressed',b===rt));save();renderNav(route);buildToc($('#col'),route.page,'pyq');toast(rt.dataset.r==='g'?'Nice — marked as known':'Added to revise list');return}
  const p=e.target.closest('.ans-body>p,.ans-body li,.chsec>p,.chsec li,.co-b>p');
  if(p&&e.detail===2&&p.dataset.hk){p.classList.toggle('p-hl');p.classList.contains('p-hl')?hl.add(p.dataset.hk):hl.delete(p.dataset.hk);save();win.getSelection().removeAllRanges()}
});

function buildToc(col,key,pn){
  const items=[];
  $$('.part,.chsec,.ans',col).forEach(el=>{
    if(el.classList.contains('part'))items.push({g:el.querySelector('h2').textContent,t:null});
    else if(el.classList.contains('ans'))items.push({id:el.id,t:el.querySelector('.qt').textContent,s:el.querySelector('.chip.y').textContent+' · '+el.querySelectorAll('.chip')[1].textContent.split(' ·').pop().trim(),el});
    else{const h=el.querySelector('h2');items.push({id:el.dataset.id,t:h.textContent,s:(el.querySelector('.eyebrow')||{}).textContent||'',el})}
  });
  const ids=items.filter(i=>i.id).map(i=>i.id);const dn=ids.filter(i=>done.has(i)||rate[i]==='g').length;
  const html=`<h5>${pn==='pyq'?'Questions':'Contents'}</h5>${ids.length?`<div class="pbar"><i style="transform:scaleX(${dn/ids.length})"></i></div>`:''}`+items.map(i=>i.t===null?`<div class="grp">${esc(i.g)}</div>`:`<button data-t="${i.id}" class="${done.has(i.id)||rate[i.id]==='g'?'done':''}">${i.s?`<small>${esc(i.s)}</small>`:''}${esc(i.t.length>70?i.t.slice(0,68)+'…':i.t)}</button>`).join('');
  $$('.toc',view).forEach(t=>t.innerHTML=html);
  $$('.toc button',view).forEach(b=>b.onclick=()=>{const el=byId(b.dataset.t);const s=el.closest('.chsec');if(s)s.classList.remove('fold');el.scrollIntoView({behavior:'smooth',block:'start'});const d=b.closest('details');if(d)d.open=false});
  if(spy)spy.disconnect();
  spy=new IntersectionObserver(es=>{es.forEach(e=>{if(e.isIntersecting){$$('.toc button',view).forEach(b=>b.classList.toggle('on',b.dataset.t===e.target.id||b.dataset.t===e.target.dataset.id))}})},{rootMargin:'-90px 0px -70% 0px'});
  items.forEach(i=>i.el&&spy.observe(i.el));
}

/* ---- decks built from the tables in the notes ---- */
function deck(unitKey){
  const out=[];let g=0;
  Object.entries(panels).forEach(([k,p])=>{
    const u=k.split('/')[0];if(unitKey&&unitKey!==u)return;
    $$('table',p).forEach(t=>{
      const rows=$$('tr',t);if(rows.length<3)return;
      const hs=$$('th',rows[0]).map(x=>x.textContent.trim());g++;
      if(hs.length===2&&/^(concept|term|abbreviation|topic|competency|importance|mistake)$/i.test(hs[0])){
        $$('tbody tr',t).forEach(r=>{const c=$$('td',r);if(c.length!==2)return;
          const f=c[0].textContent.trim(),b=c[1].textContent.trim();if(f&&b&&f.length<90&&b.length<300)out.push({f,b,h:hs[1],u,g,kind:'def'})});
      }else if(hs.length>=3&&hs.length<=4&&/^(basis|point|feature|aspect|criteria|parameter|factor|difference)/i.test(hs[0])){
        $$('tbody tr',t).forEach(r=>{const c=$$('td',r).map(x=>x.textContent.trim());if(c.length!==hs.length)return;
          for(let i=1;i<hs.length;i++)if(c[i]&&c[i].length<260&&c[0])out.push({f:hs[i],lbl:c[0],b:c[i],h:'Compare',u,g,kind:'cmp'})});
      }
    });
  });
  const seen=new Set();return out.filter(c=>{const k=c.f.toLowerCase()+'|'+(c.lbl||'')+'|'+c.b.toLowerCase();if(seen.has(k))return false;seen.add(k);return true});
}
function unitChips(cur,base){return `<div class="chips-row">${[['','All'],...META.units.map(u=>[u.key,'Unit '+u.roman]),['rev','Revision']].map(([k,l])=>`<button aria-pressed="${(cur||'')===k}" data-go="#/${base}${k?'/'+k:''}">${l}</button>`).join('')}</div>`}
let C={i:0,list:[]};
function cards(){
  const uk=route.a||'';let list=deck(uk);
  if(LS.get('shuf',false))list=list.slice().sort(()=>Math.random()-.5);
  C={i:0,list};
  view.innerHTML=`<div class="uhead" style="text-align:center"><div class="eyebrow-l">Flashcards</div><h1>Flip, recall, repeat</h1><p style="margin:0 auto">Built from the definition and comparison tables in the notes. Click the card or press Space to flip, ← → to move.</p></div>${unitChips(uk,'cards')}<div class="stage" id="stage"></div>`;
  fc();
}
function fc(){
  const s=$('#stage');if(!C.list.length){s.innerHTML='<div class="empty">No cards for this selection.</div>';return}
  const c=C.list[C.i];
  s.innerHTML=`<div class="fc" id="fcd"><div class="fc-in"><div class="face"><small>${U[c.u]?'Unit '+U[c.u].roman:'Revision'} · ${c.kind==='cmp'?'Compare':'Define'}</small><b>${esc(c.f)}</b>${c.lbl?`<span style="color:var(--text2)">${esc(c.lbl)}</span>`:''}<small style="margin-top:14px">Tap to flip</small></div><div class="face back"><small>Answer</small><span>${esc(c.b)}</span></div></div></div>
  <div class="ctl"><button class="btn sec" id="pv">← Previous</button><button class="btn sec" id="sh">Shuffle</button><button class="btn" id="nx">Next →</button></div><div class="cnt">${C.i+1} / ${C.list.length}</div>`;
  $('#fcd').onclick=()=>$('#fcd').classList.toggle('flip');
  $('#pv').onclick=()=>{C.i=(C.i-1+C.list.length)%C.list.length;fc()};
  $('#nx').onclick=()=>{C.i=(C.i+1)%C.list.length;fc()};
  $('#sh').onclick=()=>{C.list.sort(()=>Math.random()-.5);C.i=0;fc();toast('Shuffled')};
}

/* ---- quiz ---- */
let Q={};
function quiz(){
  const uk=route.a||'';const cards=deck(uk);
  view.innerHTML=`<div class="uhead" style="text-align:center"><div class="eyebrow-l">Quiz</div><h1>Test yourself</h1><p style="margin:0 auto">Ten questions drawn from the definitions and comparisons in the notes.</p></div>${unitChips(uk,'quiz')}<div class="stage" id="stage"></div>`;
  const pool=cards.filter(c=>c.b.length>8).sort(()=>Math.random()-.5).slice(0,10);
  if(pool.length<4){$('#stage').innerHTML='<div class="empty">Not enough material for a quiz here.</div>';return}
  const rnd=a=>a.slice().sort(()=>Math.random()-.5);
  Q={i:0,s:0,qs:pool.map(c=>{const same=rnd(cards.filter(x=>x.b!==c.b&&x.g===c.g)),rest=rnd(cards.filter(x=>x.b!==c.b&&x.kind===c.kind));
    const w=[...new Set([...same,...rest].map(x=>x.b))].slice(0,3);
    return{q:c.kind==='cmp'?`Which describes “${c.f}” for “${c.lbl}”?`:`What is “${c.f}”?`,a:c.b,o:rnd([...w,c.b])}})};
  qn();
}
function qn(){
  const s=$('#stage');
  if(Q.i>=Q.qs.length){const p=Math.round(Q.s/Q.qs.length*100);s.innerHTML=`<div class="qz"><div class="score">${Q.s}/${Q.qs.length}</div><p style="text-align:center;color:var(--text2)">${p>=80?'Excellent — you are exam ready on these.':p>=50?'Good. Revisit the ones you missed.':'Keep going — flip through the flashcards first.'}</p><div class="ctl" style="margin-top:16px"><button class="btn" id="ag">Try new questions</button><button class="btn sec" data-go="#/cards${route.a?'/'+route.a:''}">Open flashcards</button></div></div>`;$('#ag').onclick=quiz;return}
  const q=Q.qs[Q.i];
  s.innerHTML=`<div class="qz"><div class="qbar"><i style="transform:scaleX(${Q.i/Q.qs.length})"></i></div><small style="color:var(--text2)">Question ${Q.i+1} of ${Q.qs.length}</small><h3>${esc(q.q)}</h3>${q.o.map((o,k)=>`<button class="opt" data-k="${k}">${esc(o)}</button>`).join('')}<div class="ctl" style="margin-top:14px"><button class="btn" id="nq" hidden>${Q.i+1===Q.qs.length?'See score':'Next'}</button></div></div>`;
  $$('.opt',s).forEach(b=>b.onclick=()=>{const ok=q.o[b.dataset.k]===q.a;if(ok)Q.s++;$$('.opt',s).forEach(x=>{x.disabled=true;if(q.o[x.dataset.k]===q.a)x.classList.add('ok')});if(!ok)b.classList.add('no');$('#nq').hidden=false;$('#nq').onclick=()=>{Q.i++;qn()}});
}

/* ---- saved ---- */
function savedView(){
  const items=[...saved].map(id=>{const el=byId(id);return el?{id,t:titleOf(id),u:el.closest('.panel')}:null}).filter(Boolean);
  view.innerHTML=`<div class="uhead"><div class="eyebrow-l">Saved</div><h1>Your saved pages</h1><p>Chapters and answers you starred. ${rate?Object.values(rate).filter(v=>v==='r').length:0} answers are marked “need to revise”.</p></div><div class="col">${items.length?items.map(i=>`<div class="saved-i" data-go="#/${i.u.dataset.u}/${i.u.dataset.p}/${i.id}"><div><small>${i.u.dataset.u==='rev'?'Revision':'Unit '+U[i.u.dataset.u].roman} · ${i.u.dataset.p==='pyq'?'Solved PYQ':'Study notes'}</small>${esc(i.t)}</div></div>`).join(''):'<div class="empty">Nothing saved yet. Tap “Save” on any chapter or answer.</div>'}</div>`;
}
$('#sv').onclick=()=>go('#/saved');

/* ---- search palette ---- */
let IDX=null;
function buildIdx(){IDX=[];Object.entries(panels).forEach(([k,p])=>{const[u,pn]=k.split('/');$$('.chap h2,.part h2,.qt,h3',p).forEach(h=>{const sec=h.closest('[id]');const el=h.id?h:(h.closest('.chap,.ans,.part')||h);const id=h.id||el.id;if(!id)return;IDX.push({t:h.textContent.trim(),u,p:pn,id,lbl:(u==='rev'?'Revision':'Unit '+U[u].roman)+' · '+(pn==='pyq'?'PYQ':h.tagName==='H3'?'Section':'Chapter')})})});}
function palette(){
  if($('.pal'))return;if(!IDX)buildIdx();
  const d=document.createElement('div');d.className='pal';d.innerHTML='<div class="pal-b"><input placeholder="Search chapters, headings, questions…" autofocus><ul></ul></div>';root.appendChild(d);
  const inp=$('input',d),ul=$('ul',d);let sel=0,res=[];
  const draw=()=>{const q=inp.value.trim().toLowerCase();res=(q?IDX.filter(x=>q.split(/\s+/).every(w=>x.t.toLowerCase().includes(w))):IDX.filter(x=>x.lbl.endsWith('Chapter')).slice(0,12)).slice(0,40);sel=0;ul.innerHTML=res.map((r,i)=>`<li class="${i?'':'on'}" data-i="${i}"><span>${esc(r.t.length>80?r.t.slice(0,78)+'…':r.t)}</span><small>${r.lbl}</small></li>`).join('')||'<li><span>No results</span></li>'};
  const pick=i=>{const r=res[i];if(!r)return;d.remove();go(`#/${r.u}/${r.p}/${r.id}`)};
  inp.oninput=draw;draw();
  inp.onkeydown=e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();sel=(sel+(e.key==='ArrowDown'?1:-1)+res.length)%res.length;$$('li',ul).forEach((l,i)=>l.classList.toggle('on',i===sel));$$('li',ul)[sel].scrollIntoView({block:'nearest'})}else if(e.key==='Enter')pick(sel);else if(e.key==='Escape')d.remove()};
  d.onclick=e=>{if(e.target===d)d.remove();const li=e.target.closest('li[data-i]');if(li)pick(+li.dataset.i)};
}
$('#sbtn').onclick=palette;
doc.addEventListener('keydown',e=>{
  const typing=/input|textarea/i.test(document.activeElement.tagName);
  if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();palette()}
  else if(e.key==='/'&&!typing){e.preventDefault();palette()}
  else if(route.page==='cards'&&!typing){if(e.key==='ArrowRight')$('#nx')?.click();else if(e.key==='ArrowLeft')$('#pv')?.click();else if(e.key===' '){e.preventDefault();$('#fcd')?.click()}}
});

/* ---- chrome ---- */
let fs=LS.get('fs',17);root.style.setProperty('--fs',fs+'px');
$('#fs').onclick=()=>{fs=fs>=21?15:fs+2;root.style.setProperty('--fs',fs+'px');LS.set('fs',fs);toast('Text size '+fs+'px')};
$('#up').onclick=()=>win.scrollTo({top:0,behavior:'smooth'});
win.addEventListener('scroll',()=>{const h=document.documentElement;$('#bar').style.transform='scaleX('+(h.scrollTop/(h.scrollHeight-h.clientHeight||1))+')'},{passive:true});
render();

